const INDEX_HTML_B64 = "";

const MANIFEST_JSON_B64 = "";

const SW_JS_B64 = "";

const ICON192_B64 = "";

const ICON512_B64 = "";


function b64ToUtf8(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}

function b64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function checkPin(request, env) {
  if (!env.APP_PIN) return true; // sem PIN configurado, acesso livre
  const pin = request.headers.get('x-app-pin') || '';
  return pin === env.APP_PIN;
}

function unauthorized() {
  return new Response(JSON.stringify({ error: 'unauthorized' }), {
    status: 401,
    headers: { 'Content-Type': 'application/json' }
  });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    // --- API: lista/guarda os clientes ---
    if (path === '/api/clients') {
      if (request.method === 'GET') {
        if (!checkPin(request, env)) return unauthorized();
        const data = await env.CLIENTS_KV.get('clients');
        return new Response(data || '[]', { headers: { 'Content-Type': 'application/json' } });
      }
      if (request.method === 'POST') {
        if (!checkPin(request, env)) return unauthorized();
        let body;
        try {
          body = await request.json();
        } catch (e) {
          return new Response(JSON.stringify({ error: 'invalid json' }), { status: 400 });
        }
        if (!Array.isArray(body)) {
          return new Response(JSON.stringify({ error: 'expected array' }), { status: 400 });
        }
        await env.CLIENTS_KV.put('clients', JSON.stringify(body));
        return new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } });
      }
      return new Response('Method not allowed', { status: 405 });
    }

    // --- Ficheiros estáticos da PWA ---
    if (path === '/manifest.json') {
      return new Response(b64ToUtf8(MANIFEST_JSON_B64), { headers: { 'Content-Type': 'application/json' } });
    }
    if (path === '/sw.js') {
      return new Response(b64ToUtf8(SW_JS_B64), { headers: { 'Content-Type': 'application/javascript' } });
    }
    if (path === '/icon-192.png') {
      return new Response(b64ToBytes(ICON192_B64), { headers: { 'Content-Type': 'image/png' } });
    }
    if (path === '/icon-512.png') {
      return new Response(b64ToBytes(ICON512_B64), { headers: { 'Content-Type': 'image/png' } });
    }

    // --- Tudo o resto: a app ---
    return new Response(b64ToUtf8(INDEX_HTML_B64), { headers: { 'Content-Type': 'text/html;charset=UTF-8' } });
  }
};
